/**
 * 制作资产的三张版式引导参考图（内联 base64 data URI）。
 *
 * 为什么内联：节点构建产物是单文件 UMD，没有任何随包资源目录，任何随功能分发的图片
 * 只能进代码。三张原图各约 100-400KB，用内置 ffmpeg 压到 960 宽、q:v 5 后共约 74KB，
 * base64 后约 99KB，产物增幅可控。
 *
 * 三张都是**空白灰模**（无服装、无个人特征），只讲版式不讲人，不会污染角色身份。
 * 唯一区别在右段头部格数：一个头 / 两个头 / 三个头。
 *
 * 原始比例（决定各版式画幅）：
 * - 单头 1376×768 ≈ 1.79 → 16:9
 * - 双头 1200×896 ≈ 1.34 → 4:3
 * - 三头 1200×896 ≈ 1.34 → 4:3
 */
export const MULTIVIEW_ONE_HEAD_REF = "data:image/jpeg;base64,";
export const MULTIVIEW_TWO_HEADS_REF = "data:image/jpeg;base64,";
export const MULTIVIEW_THREE_HEADS_REF = "data:image/jpeg;base64,";
